    pub(crate) fn compare_os_task_proxy(
        &self,
        other: &Document,
        a: &OsTaskProxy,
        b: &OsTaskProxy,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_period() != b.get_period() {
            return Err(format!("{path}: PERIOD mismatch"));
        }
        if a.get_preemptability() != b.get_preemptability() {
            return Err(format!("{path}: PREEMPTABILITY mismatch"));
        }
        if a.get_priority() != b.get_priority() {
            return Err(format!("{path}: PRIORITY mismatch"));
        }
        Ok(())
    }

